function Write-EntraCAAssessmentLog{[CmdletBinding()]param([Parameter(Mandatory)][string]$Message,[ValidateSet("Info","Warning","Error","Success")][string]$Level="Info",[string]$LogRoot=(Join-Path $PSScriptRoot "../../Logs/Assessment"));if(-not (Test-Path $LogRoot)){New-Item -ItemType Directory -Path $LogRoot -Force|Out-Null};$c=@{Info="Cyan";Warning="Yellow";Error="Red";Success="Green"};Write-Host "[$Level] $Message" -ForegroundColor $c[$Level];$e=[PSCustomObject]@{Timestamp=(Get-Date).ToString("o");Level=$Level;Message=$Message};$e|ConvertTo-Json -Compress|Add-Content -Path (Join-Path $LogRoot ("assessment-{0}.log" -f (Get-Date -Format "yyyy-MM-dd"))) -Encoding UTF8}